import Foundation
import Vision
import AppKit
import Quartz

let path = CommandLine.arguments[1]
let doc = PDFDocument(url: URL(fileURLWithPath: path))!
for i in 0..<doc.pageCount {
    let page = doc.page(at: i)!
    let rect = page.bounds(for: .mediaBox)
    let scale: CGFloat = 3.0
    let img = NSImage(size: NSSize(width: rect.width*scale, height: rect.height*scale))
    img.lockFocus()
    let ctx = NSGraphicsContext.current!.cgContext
    ctx.setFillColor(CGColor.white); ctx.fill(CGRect(x:0,y:0,width:rect.width*scale,height:rect.height*scale))
    ctx.scaleBy(x: scale, y: scale)
    page.draw(with: .mediaBox, to: ctx)
    img.unlockFocus()
    var pr = CGRect(x:0,y:0,width:rect.width*scale,height:rect.height*scale)
    guard let cg = img.cgImage(forProposedRect: &pr, context: nil, hints: nil) else { continue }
    let req = VNRecognizeTextRequest()
    req.recognitionLevel = .accurate
    req.usesLanguageCorrection = false
    try? VNImageRequestHandler(cgImage: cg, options: [:]).perform([req])
    print("===== PAGE \(i+1) =====")
    for obs in (req.results ?? []) {
        if let t = obs.topCandidates(1).first { print(t.string) }
    }
}
